/**
 * @name Command injection from YAML
 * @description YAML content flowing to system commands could allow command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/yaml-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module YamlCommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("yaml").getMember(["load", "load_all", "safe_load", "safe_load_all"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module YamlCommandInjectionFlow = TaintTracking::Global<YamlCommandInjectionConfig>;

import YamlCommandInjectionFlow::PathGraph

from YamlCommandInjectionFlow::PathNode source, YamlCommandInjectionFlow::PathNode sink
where YamlCommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "YAML content flows to system command execution $@.", source.getNode(), "from YAML parsing"
